var origpayload = msg.payload;
// Handle both old format { msg: "Success", data: { access_token: ... } } and new format { code: 0, data: { access_token: ... } }
var tokenData = null;
if (origpayload.msg == "Success" && origpayload.data && origpayload.data.access_token) {
    // Old format
    tokenData = origpayload.data;
} else if (origpayload.data && origpayload.data.access_token) {
    // New format from /oauth/token/new
    tokenData = origpayload.data;
} else if (origpayload.code === 0 && origpayload.data && origpayload.data.access_token) {
    // Alternative new format
    tokenData = origpayload.data;
}

if (tokenData && tokenData.access_token) {
    global.set("SS.BearerReturn", tokenData);
    msg.payload = tokenData.access_token;
    global.set("SS.Bearer", msg.payload);
    global.set("SS.Header.Bearer.Authorization", "Bearer " + msg.payload);
    let currdate = new Date();
    node.status("Token received - " + currdate.toLocaleString());
    if (global.get("SunSynkDebug") === 1) {
        node.error(msg);
    }
    var msgstatus = {};
    msgstatus.payload = {};
    msgstatus.payload.state = msg.payload;
    return [msgstatus, msg];
} else {
    msg.payload = {};
    var errorMsg = origpayload.msg || origpayload.message || "Unknown error";
    node.status(errorMsg);
