// New authentication mechanism: Get public key, encrypt password, then login
// crypto is available from libs configuration

function toPemPublicKey(base64Key) {
    const chunks = base64Key.match(/.{1,64}/g) || [base64Key];
    return (
        "-----BEGIN PUBLIC KEY-----\n" +
        chunks.join("\n") +
        "\n-----END PUBLIC KEY-----\n"
    );
}

// Get credentials
const username = global.get("SS.username");
const password = global.get("SS.password");
const region = global.get("SS.Region");
const ErrorCk = global.get("SS.ErrorCk");

if (ErrorCk.includes(username) || ErrorCk.includes(password)) {
    node.error("Username or password not set");
    node.status("Credentials missing");
    return null;
}

// Step 1: Create nonce and sign string, then MD5 hash
const now = Date.now();
const signString = `nonce=${now}&source=sunsynkPOWER_VIEW`;
const hash = crypto.createHash("md5").update(signString).digest("hex");

if (global.get("SunSynkDebug") === 1) {
    node.error("Nonce: " + now);
    node.error("Sign string: " + signString);
    node.error("MD5 hash: " + hash);
}

// Step 2: Prepare public key request
// Public key endpoint always uses api.sunsynk.net regardless of region
const publicKeyUrl = `https://api.sunsynk.net/anonymous/publicKey?nonce=${now}&source=sunsynk&sign=${hash}`;

// Store values for next step and set URL for HTTP request
msg.url = publicKeyUrl;
msg.method = "GET";
msg.headers = {
    "accept": "application/json"
};
msg.username = username;
msg.password = password;
msg.region = region;
msg.nonce = now;
msg.hash = hash;

if (global.get("SS.Config.certcheck") === "False") {
    msg.rejectUnauthorized = false;
}

if (global.get("SunSynkDebug") === 1) {
    node.error("Public key URL: " + publicKeyUrl);
}

node.status("Requesting public key...");
return msg;

// Step 3: Encrypt password using RSA + PKCS1 padding
// crypto is available from libs configuration

function toPemPublicKey(base64Key) {
    const chunks = base64Key.match(/.{1,64}/g) || [base64Key];
    return (
        "-----BEGIN PUBLIC KEY-----\n" +
        chunks.join("\n") +
        "\n-----END PUBLIC KEY-----\n"
    );
}

const ErrorCk = global.get("SS.ErrorCk");

// Check if this is an error response
if (msg.statusCode && msg.statusCode !== 200) {
    var errorDetails = "Status: " + msg.statusCode;
    if (msg.payload) {
        errorDetails += ", Payload: " + JSON.stringify(msg.payload);
    }
    if (msg.error) {
        errorDetails += ", Error: " + msg.error;
    }
    if (msg.responseUrl) {
        errorDetails += ", URL: " + msg.responseUrl;
    }
    node.error("HTTP error getting public key: " + errorDetails);
    node.status("HTTP error: " + msg.statusCode);
    return null;
}

// Check if public key response is valid
if (!msg.payload || typeof msg.payload !== 'object') {
    node.error("Invalid public key response (not JSON): " + JSON.stringify(msg.payload));
    node.status("Invalid response format");
    return null;
}

if (!msg.payload.data) {
    node.error("Public key response missing data field: " + JSON.stringify(msg.payload));
    node.status("Missing data field");
    return null;
}

const publicKeyBase64 = msg.payload.data;
const publicKeyPem = toPemPublicKey(publicKeyBase64);

// Get stored values from previous step
const username = msg.username || global.get("SS.username");
const password = msg.password || global.get("SS.password");
const region = msg.region || global.get("SS.Region");

if (ErrorCk.includes(username) || ErrorCk.includes(password)) {
    node.error("Username or password missing");
    return null;
}

// Encrypt password
let encryptedPassword;
try {
    encryptedPassword = crypto
        .publicEncrypt(
            {
                key: publicKeyPem,
                padding: crypto.constants.RSA_PKCS1_PADDING,
            },
            Buffer.from(password, "utf8")
        )
        .toString("base64");
} catch (err) {
    node.error("Password encryption failed: " + err.message);
    node.status("Encryption error");
    return null;
}

if (global.get("SunSynkDebug") === 1) {
    node.error("Encrypted password (base64): " + encryptedPassword);
}

// Step 4: Prepare login request body
const loginBody = {
    areaCode: "sunsynk",
    client_id: "csp-web",
    grant_type: "password",
    password: encryptedPassword,
    source: "sunsynk",
    username: username,
};

// Set up the login request
msg.url = global.get("SS.url.token");
msg.method = "POST";
msg.requestTimeout = parseInt(global.get("SS.Config.timeout"));
msg.payload = loginBody;
msg.headers = {
    "accept": "application/json",
    "content-type": "application/json"
};

if (global.get("SS.Config.certcheck") === "False") {
    msg.rejectUnauthorized = false;
}

let currdate = new Date();
node.status("Login request prepared - " + currdate.toLocaleString());
if (global.get("SunSynkDebug") === 1) {
    node.error(msg);
}

return msg;

