function do_value_gatewaystatus(s_payload, t_gsn) {
    var t_value = "False";
    if (global.get("SunSynkDebug") === 1) { node.error(s_payload); }
    for (let i = 0; i < s_payload.length; i++) 
    {
      if (s_payload[i].sn === t_gsn )
      {
        if (s_payload[i].uploadCycle < 61 ) 
         { 
            t_value = "True" ;
         } 
         else 
         {  
            t_value = "Gather" ;
            global.set("SS_Consolid.LongDelay", true);
            node.error(" Gateway is bad. Not configured for <= 60s cycle rate. Updates Disabled ") ; 
         }
      }
    }
    if (global.get("SS_Consolid.Gateways.total") === 0) {
        t_value = "True";
        if (global.get("SS.Config.force_short_delay") === "true" )
        {
            global.set("SS_Consolid.LongDelay", false);    
            node.error(" 0 Gateways Found. Enable gather/update.Long Delay Forced Disabled");
        } else
        {
            global.set("SS_Consolid.LongDelay", true);
            node.error(" 0 Gateways Found. Enable gather/update.Set Long Delay");
        }
    } 
    return t_value;
}


